// Builds the GuidelinesResponse (shape: src/api/types.ts) from the "guidelines" data table.
// Edit the content in the data table, not here. Internal text: never copy it into the public repo.
// One row per line, sorted by position. kind values:
// title | intro | heading | paragraph | bullet | numbered | sub_bullet | closing
const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());

const rows = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0 && r.active !== false)
  .sort((a, b) => (Number(a.position) || 0) - (Number(b.position) || 0));

const out = { title: '', intro: '', sections: [], closing: '' };
let section = null; // current section
let list = null; // current list block
let lastItem = null; // last bullet or numbered item (parent for sub_bullets)

const ensureSection = () => {
  if (!section) {
    section = { heading: '', blocks: [] };
    out.sections.push(section);
  }
  return section;
};
const endList = () => {
  list = null;
  lastItem = null;
};
const startList = (ordered) => {
  list = { type: 'list', ordered, items: [] };
  ensureSection().blocks.push(list);
};

for (const r of rows) {
  const kind = clean(r.kind).toLowerCase();
  const lead = clean(r.lead);
  const text = clean(r.text);

  if (kind === 'title') out.title = text;
  else if (kind === 'intro') out.intro = text;
  else if (kind === 'closing') out.closing = text;
  else if (kind === 'heading') {
    section = { heading: text, blocks: [] };
    out.sections.push(section);
    endList();
  } else if (kind === 'paragraph') {
    if (!text) continue;
    ensureSection().blocks.push({ type: 'paragraph', text });
    endList();
  } else if (kind === 'bullet' || kind === 'numbered') {
    if (!lead && !text) continue;
    const ordered = kind === 'numbered';
    if (!list || list.ordered !== ordered) startList(ordered);
    lastItem = { lead, text, items: [] };
    list.items.push(lastItem);
  } else if (kind === 'sub_bullet') {
    if (!text) continue;
    if (lastItem) {
      lastItem.items.push(text);
    } else {
      // Parent bullet missing (e.g. deleted): show it as a normal bullet instead.
      if (!list || list.ordered) startList(false);
      list.items.push({ lead: '', text, items: [] });
    }
  }
  // Unknown kinds are ignored.
}

// Leave out sections that ended up with no content.
out.sections = out.sections.filter((s) => s.blocks.length > 0);

return [{ json: out }];
